package com.ecommerce.notification.service;
@org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="services.notification.delivery-enabled",havingValue="true",matchIfMissing=true)
@org.springframework.stereotype.Service public class SmsWorker {private final com.ecommerce.notification.repo.SmsDeliveryRepository jobs;private final com.ecommerce.notification.repo.CustomerRepository customers;private final SmsService sms;public SmsWorker(com.ecommerce.notification.repo.SmsDeliveryRepository j,com.ecommerce.notification.repo.CustomerRepository c,SmsService s){jobs=j;customers=c;sms=s;}@org.springframework.scheduling.annotation.Scheduled(fixedDelay=5000) public void run(){for(var job:jobs.findTop20ByStateAndNextAttemptAtLessThanEqual("PENDING",java.time.Instant.now())){try{if(!sms.isConfigured())job.state="DEMO_SKIPPED";else{var customer=customers.findById(job.customerId).orElseThrow();if(sms.sendSms(customer.getPhone(),job.message))job.state="SENT";}}catch(RuntimeException retry){}job.attempts++;job.nextAttemptAt=java.time.Instant.now().plusSeconds(Math.min(3600,30L*job.attempts));jobs.save(job);}}}